// @generated by:gauntlet run:godseye-local-hermes-chat
import { createHash, randomUUID } from "node:crypto";
import {
  type AgentConversationDetailView,
  CONTROL_API_HEADER,
  CONTROL_API_VERSION,
} from "@godseye/contracts";
import type { Page } from "@playwright/test";

/** UI contract only; owner enrollment, project/profile and conversation exist in the real API. */
export async function chatBrowserResponses(
  page: Page,
  options: { loseFirstSendReply?: boolean } = {},
) {
  const detail = (await page.evaluate(async () => {
    const list = (await (await fetch("/api/v1/agents/conversations")).json()) as {
      conversations: { id: string }[];
    };
    const id = list.conversations[0]?.id;
    if (!id) throw new Error("No real owner conversation for UI fixture");
    return (await fetch(`/api/v1/agents/conversations/${id}`)).json();
  })) as AgentConversationDetailView;
  const headers = { "content-type": "application/json", [CONTROL_API_HEADER]: CONTROL_API_VERSION };
  const posts: { input: string; expectedRevision: number; key: string }[] = [];
  const decisions: unknown[] = [];
  let streamCount = 0;
  await page.route(`**/api/v1/agents/conversations/${detail.conversation.id}`, (route) =>
    route.fulfill({ status: 200, headers, body: JSON.stringify(detail) }),
  );
  await page.route(
    `**/api/v1/agents/conversations/${detail.conversation.id}/turns`,
    async (route) => {
      const payload = route.request().postDataJSON() as { input: string; expectedRevision: number };
      posts.push({
        input: payload.input,
        expectedRevision: payload.expectedRevision,
        key: route.request().headers()["idempotency-key"] ?? "",
      });
      if (options.loseFirstSendReply && posts.length > 1) {
        await route.fulfill({ status: 202, headers, body: JSON.stringify(detail) });
        return;
      }
      const now = new Date().toISOString();
      detail.conversation.revision++;
      detail.turns.push({
        id: randomUUID(),
        conversationId: detail.conversation.id,
        sequence: 0,
        partialText: "",
        omittedTurns: 0,
        task: {
          id: randomUUID(),
          profileId: detail.conversation.profileId,
          projectId: detail.conversation.projectId,
          environmentId: detail.conversation.environmentId,
          profileRevision: detail.conversation.profileRevision,
          runId: randomUUID(),
          state: "running",
          providerRunId: `run_${randomUUID().replaceAll("-", "")}`,
          input: payload.input,
          output: null,
          reason: null,
          usage: { inputTokens: null, outputTokens: null, costState: "reserved-conservatively" },
          createdAt: now,
          updatedAt: now,
          finishedAt: null,
        },
      });
      if (options.loseFirstSendReply) await route.abort("failed");
      else await route.fulfill({ status: 202, headers, body: JSON.stringify(detail) });
    },
  );
  await page.route(
    `**/api/v1/agents/conversations/${detail.conversation.id}/events?*`,
    async (route) => {
      streamCount++;
      let body = `event: ready\ndata: ${JSON.stringify({ version: CONTROL_API_VERSION, cursor: detail.conversation.cursor })}\n\n`;
      const turn = detail.turns[0];
      if (turn && !turn.partialText) {
        const text = "Texte provisoire réellement reçu par EventSource.";
        body += `id: 1\nevent: chat\ndata: ${JSON.stringify({
          conversationId: detail.conversation.id,
          cursor: 1,
          turnId: turn.id,
          type: "text.delta",
          text,
          state: null,
          occurredAt: new Date().toISOString(),
        })}\n\n`;
        turn.partialText = text;
        detail.conversation.cursor = 1;
      }
      await route.fulfill({
        status: 200,
        headers: { ...headers, "content-type": "text/event-stream" },
        body,
      });
    },
  );
  await page.route("**/api/v1/agents/proposals/*/resolve", async (route) => {
    const value = route.request().postDataJSON() as {
      decision: "approve" | "reject";
      expectedHash: string;
    };
    decisions.push(value);
    const proposal = detail.proposals[0];
    if (!proposal) throw new Error("No UI contract proposal");
    proposal.status = value.decision === "approve" ? "approved" : "rejected";
    proposal.resolvedAt = new Date().toISOString();
    await route.fulfill({ status: 200, headers, body: JSON.stringify(proposal) });
  });
  return {
    posts,
    decisions,
    streamCount: () => streamCount,
    complete() {
      const turn = detail.turns[0];
      if (!turn) throw new Error("Send a UI fixture turn first");
      turn.task.state = "succeeded";
      turn.task.output = "Réponse finale du contrat UI.";
      turn.task.finishedAt = new Date().toISOString();
      const content = "<script>window.__chatXss=true</script>\nBrouillon privé";
      detail.artifacts.push({
        id: randomUUID(),
        conversationId: detail.conversation.id,
        turnId: turn.id,
        taskId: turn.task.id,
        name: `draft-${randomUUID()}.md`,
        mediaType: "text/markdown",
        content,
        sha256: createHash("sha256").update(content).digest("hex"),
        bytes: Buffer.byteLength(content),
        createdAt: new Date().toISOString(),
      });
      detail.proposals.push({
        id: randomUUID(),
        conversationId: detail.conversation.id,
        turnId: turn.id,
        taskId: turn.task.id,
        planId: randomUUID(),
        expectedHash: "a".repeat(64),
        projectId: detail.conversation.projectId,
        environmentId: detail.conversation.environmentId,
        targetId: detail.conversation.environmentId,
        expectedRevision: 0,
        command: JSON.stringify({ kind: "deployment.release", intent: "deploy" }),
        reason: "Proposition du contrat UI, aucune exécution réelle.",
        status: "pending",
        createdAt: new Date().toISOString(),
        expiresAt: new Date(Date.now() + 3600000).toISOString(),
        resolvedAt: null,
      });
    },
  };
}
